edits.content:
frame = [["." for _ in range(m)] for _ in range(n)]
for i in range(n):
    for j in range(m):
        if monitor[i][j] == "w":
            frame[i][j] = "w"
for i in range(n):
    frame[i][min_frame[1]] = "+"
    frame[i][min_frame[1] + min_frame_size - 1] = "+"
for j in range(m):
    frame[min_frame[0]][j] = "+"
    frame[min_frame[0] + min_frame_size - 1][j] = "+"
for i in range(n):
    for j in range(m):
        if frame[i][j] == "+":
            frame[i][j] = "+"
        elif frame[i][j] == ".":
            frame[i][j] = "."
return "\n".join(["".join(row) for row in frame])

