edits.content:
min_removed = 0
for i in range(H):
    for j in range(W):
        if grid[i][j] == "o":
            new_grid = [row[:] for row in grid]
            for ni, nj in get_adjacent_cells(H, W, i, j):
                new_grid[ni][nj] = "."
            if not dfs(H, W, new_grid, S_i, S_j, T_i, T_j, set()):
                min_removed += 1
return min_removed

