ans.extend([(1, v) for v in adj[1][:D]])
for i in range(n - 1, 0, -1):
    if i != 1:
        for v in adj[i]:
            if (
                find(i, p) != find(v, p)
                and (i, v) not in ans
                and (v, i) not in ans
            ):
                ans.append((i, v))
                union(i, v, p, sz)
if len(ans) == n - 1:
    print("\n".join(" ".join(map(str, e)) for e in ans))
    return

