edits.content:
max_len = 0
for i in range(n):
    if s[i] == t[i]:
        max_len += 1
    else:
        break

max_c = (k + 1) * max_len

for i in range(n):
    if s[i] != t[i]:
        max_c += (k - 1) * (i - max_len + 1)

return max_c

